c4Model(name = "Email Service Model") {
    val employee = person(name = "Employee") { description = "End user accessing mailboxes" }
    val admin = person(name = "Administrator") { description = "Manages service and user accounts" }
    val emailSystem = softwareSystem(name = "Email Service") {
        container(name = "Webmail Frontend") { technology = "React/TypeScript"; description = "Web UI for accessing mailboxes" }
        container(name = "Mail API") { technology = "Kotlin/Spring Boot"; description = "Handles sending and retrieval of emails" }
        container(name = "Database") { technology = "PostgreSQL"; description = "Stores messages and mailbox data" }
    }
    val spamFilter = softwareSystem(name = "Spam Filter Service") { external = true }
    relationship(source = employee, target = emailSystem) { technology = "HTTPS"; description = "Accesses mailboxes via webmail" }
    relationship(source = admin, target = emailSystem) { technology = "HTTPS"; description = "Configures service and manages accounts" }
    relationship(source = emailSystem, target = spamFilter) { technology = "SMTP"; description = "Sends incoming messages for spam inspection" }
    relationship(source = spamFilter, target = emailSystem) { technology = "SMTP"; description = "Returns filtered messages" }
    containerDiagram(name = "Email Service - Container View") { system = emailSystem; showExternalSystems = true }
}

c4Model(name = "BlogPlatform") {
    val author = person(name = "Author") { description = "Writes and publishes articles" }
    val reader = person(name = "Reader") { description = "Consumes published articles" }
    val blogPlatform = softwareSystem(name = "Blog Platform") {
        container(name = "Web Application") { technology = "React SPA"; description = "Serves UI for authors and readers" }
        container(name = "Content API") { technology = "Node.js/Express"; description = "Business logic for articles" }
        container(name = "Article Database") { technology = "PostgreSQL"; description = "Stores articles" }
    }
    val emailService = softwareSystem(name = "Email Delivery Service") { external = true }
    relationship(source = author, target = blogPlatform) { technology = "HTTPS"; description = "Writes articles" }
    relationship(source = reader, target = blogPlatform) { technology = "HTTPS"; description = "Reads articles" }
    relationship(source = blogPlatform, target = emailService) { technology = "SMTP"; description = "Sends notifications" }
    containerDiagram(name = "Blog Platform - Container View") { system = blogPlatform; showExternalSystems = true }
}

c4Model(name = "ParkingGarage") {
    val operator = person(name = "Operator") { description = "Parking garage operator who monitors and controls the facility" }
    val centralSystem = softwareSystem(name = "Central Management System") {
        container(name = "Control Service") { technology = "Kotlin/Spring Boot"; description = "Controls entry/exit barriers and occupancy" }
        container(name = "Occupancy API") { technology = "REST"; description = "Provides current occupancy count" }
        container(name = "Database") { technology = "PostgreSQL"; description = "Persists occupancy data and ticket information" }
        container(name = "Display Driver") { technology = "MQTT"; description = "Pushes available capacity to entrance displays" }
    }
    val paymentNetwork = softwareSystem(name = "Payment Terminal Network") { external = true }
    relationship(source = operator, target = centralSystem) { technology = "HTTPS"; description = "Monitors and controls" }
    relationship(source = centralSystem, target = paymentNetwork) { technology = "REST"; description = "Queries payment status" }
    containerDiagram(name = "ParkingGarage - Container View") { system = centralSystem; showExternalSystems = true }
}

c4Model(name = "Production Plant Monitoring") {
    val technician = person(name = "Plant Technician") { description = "Uses dashboard for fault diagnosis" }
    val manager = person(name = "Plant Manager") { description = "Uses dashboard for overview of utilization and energy consumption" }
    val sensorGateways = softwareSystem(name = "Sensor Gateways") { external = true; description = "Distributed sensor gateways delivering measurement values" }
    val monitoringSystem = softwareSystem(name = "Production Plant Monitoring System") {
        container(name = "Ingest Service") { technology = "Kotlin/Spring Boot"; description = "Receives measurement data and writes to time-series database" }
        container(name = "Time-Series Database") { technology = "InfluxDB"; description = "Stores measurement time series" }
        container(name = "Web Application") { technology = "React/Node.js"; description = "Generates live views and trend charts" }
        container(name = "Dashboard") { technology = "Web UI"; description = "Displays data to technicians and managers" }
    }
    relationship(source = technician, target = monitoringSystem) { technology = "HTTPS"; description = "Uses dashboard" }
    relationship(source = manager, target = monitoringSystem) { technology = "HTTPS"; description = "Uses dashboard" }
    relationship(source = sensorGateways, target = monitoringSystem) { technology = "MQTT"; description = "Delivers measurement values" }
    containerDiagram(name = "Production Plant Monitoring System - Container View") { system = monitoringSystem; showExternalSystems = true }
}

